package com.example.starter.ride;

/**
 * 设备状态机：日检→试运行→开放→运行监测→闭园复检/归档。
 * 单状态字段保证“停运”与“开放”互斥，形成唯一终态。
 */
public enum RideStatus {

    /** 待日检（初始状态，未日检设备无法开放） */
    PENDING_CHECK,

    /** 日检合格，可进行空载试运行 */
    CHECKED,

    /** 试运行恰3次合格，可开放载客 */
    READY,

    /** 开放载客，接受运行监测读数 */
    OPEN,

    /** 载荷或速度超阈值触发缓停，须复检合格方可复开 */
    SUSPENDED,

    /** 故障停运（安全装置失效或试运行异常），须复检合格方可复开 */
    STOPPED,

    /** 复检合格，可执行复开（受同日复开次数限制） */
    RECHECKED,

    /** 闭园归档，终态；迟到运行数据只记迟到事件 */
    ARCHIVED
}

package com.example.starter.ride;

import java.time.LocalDate;

/**
 * 游乐设施主表实体（合成数据）。
 *
 * @param id          设备主键
 * @param name        设备名称
 * @param status      当前状态，见 {@link RideStatus}
 * @param maxLoad     载荷阈值（人），恰等阈值合格
 * @param maxSpeed    速度阈值（rpm），恰等阈值合格
 * @param trialCount  当日已连续合格试运行次数，恰3次方可载客
 * @param reopenCount 当日复开次数，恰2次合法
 * @param checkDate   最近一次日检合格日期，NULL 表示未日检
 * @param reopenDate  最近一次复开日期，用于跨日重置复开计数
 * @param version     乐观锁版本号
 */
public record Ride(
        long id,
        String name,
        RideStatus status,
        int maxLoad,
        int maxSpeed,
        int trialCount,
        int reopenCount,
        LocalDate checkDate,
        LocalDate reopenDate,
        long version) {

    /** 安全装置检查项名称，任一失效整机立即停运。 */
    public static final String[] SAFETY_DEVICES = {"压杠", "安全带", "联锁装置"};

    /** 试运行合法次数：恰3次空载无异常方可载客。 */
    public static final int REQUIRED_TRIAL_COUNT = 3;

    /** 同日复开上限：恰2次合法，超出当日禁开。 */
    public static final int MAX_DAILY_REOPEN = 2;
}

