    private void requireStatus(Ride ride, String message, RideStatus... allowed) {
        if (Arrays.stream(allowed).noneMatch(s -> s == ride.status())) {
            throw ApiException.conflict(message + "（当前状态：" + ride.status() + "）");
        }
