            LocalDate checkDate, LocalDate reopenDate) {
        if (!rides.updateWithVersion(ride, status, trialCount, reopenCount,
                checkDate, reopenDate)) {
            throw ApiException.conflict("设备状态并发变更，请重试");
        }
