        Map<String, Object> view = new LinkedHashMap<>();
        view.put("rideId", ride.id());
        view.put("name", ride.name());
        view.put("status", ride.status().name());
        view.put("maxLoad", ride.maxLoad());
        view.put("maxSpeed", ride.maxSpeed());
