    @DisplayName("并发同键重放：全部返回首次结果，业务只执行一次")
    void concurrentSameRequestIdReplaysOnce() throws Exception {
        long rideId = createReadyRide("idem");
        int threads = 6;
        OpenRequest same = new OpenRequest("idem-open");
